// Plain-text diagnostics report for support requests, generated by the monitor command.
if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') {
    http_response_code(405);
    exit;
}
// Unraid local_prepend.php validates the POST token; fail closed without that guard.
if (!function_exists('csrf_terminate')) {
    http_response_code(403);
    exit;
}
exec('/usr/local/sbin/ugreen-pro-leds diagnostics 2>&1', $output, $status);
$name = 'ugreen-dxp4800pro-leds-diagnostics-' . date('Ymd-His') . '.txt';
header('Content-Type: text/plain; charset=utf-8');
header('Content-Disposition: attachment; filename="' . $name . '"');
header('Cache-Control: no-store');
echo implode("\n", $output), "\n";
